// 6-to-1 multiplexer (with one select wire per input, so the total number
// of gates is independent of the number of inputs; this is the optimal
// structure for this kind of mux)
module TopModule(
    input  [2:0] sel,
    input  [3:0] data0,
    input  [3:0] data1,
    input  [3:0] data2,
    input  [3:0] data3,
    input  [3:0] data4,
    input  [3:0] data5,
    output [3:0] out
);
    wire [3:0] mux [0:5];
    assign mux[0] = data0;
    assign mux[1] = data1;
    assign mux[2] = data2;
    assign mux[3] = data3;
    assign mux[4] = data4;
    assign mux[5] = data5;
    assign out = (0 <= sel && sel <= 5) ? mux[sel] : 4'd0;
endmodule

