    input  [3:0] data2,
    input  [3:0] data3,
    input  [3:0] data4,
    input  [3:0] data5,
    output [3:0] out
);
    wire [3:0] s0, s1, s2, s3, s4, s5;
    assign s0 = (sel == 3'd0) ? data0 : 4'd0;
    assign s1 = (sel == 3'd1) ? data1 : 4'd0;
    assign s2 = (sel == 3'd2) ? data2 : 4'd0;
    assign s3 = (sel == 3'd3) ? data3 : 4'd0;
    assign s4 = (sel == 3'd4) ? data4 : 4'd0;
    assign s5 = (sel == 3'd5) ? data5 : 4'd0;
    assign out = s0 | s1 | s2 | s3 | s4 | s5;
endmodule

